{"content": "package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"

	"github.com/godinj/drem-orchestrator/internal/csuite"
	"github.com/godinj/drem-orchestrator/internal/inbox"
	"github.com/google/uuid"
	"github.com/jinzhu/gorm"
)

func main() {
	db, err := setupDB() // This is a placeholder, in real app it would be configured
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to setup db: %v\n", err)
		os.Exit(1)
	}
	if err := run(os.Args[1:], db); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
}

func setupDB() (*gorm.DB, error) {
	// This is just a stub for the main function. 
	// In reality, it would use a real connection string.
	return nil, errors.New("not implemented")
}

func run(args []string, db *gorm.DB) error {
	if len(args) == 0 {
		return nil
	}

	cmd := args[0]
	switch cmd {
	case "send":
		return handleSend(args[1:], db)
	case "list":
		return handleList(args[1:], db)
	case "archive":
		return handleArchive(args[1:], db)
	case "watch":
		return handleWatch(args[1:], db)
	default:
		return fmt.Errorf("unknown command: %s", cmd)
	}
}

func handleSend(args []string, db *gorm.DB) error {
	var from, to, subject, priority, msgType, body string
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--from":
			if i+1 < len(args) {
				from = args[i+1]
				i++
			}
		case "--to":
			if i+1 < len(args) {
				to = args[i+1]
				i++
			}
		case "--subject":
			if i+1 < len(args) {
				subject = args[i+1]
				i++
			}
		case "--priority":
			if i+1 < len(args) {
				priority = args[i+1]
				i++
			}
		case "--type":
			if i+1 < len(args) {
				msgType = args[i+1]
				i++
			}
		case "--body":
			if i+1 < len(args) {
				body = args[i+1]
				i++
			}
		}
	}

	if from == "" {
		return errors.New("missing required flag: --from")
	}
	if to == "" {
		return errors.New("missing required flag: --to")
	}

	msg := &inbox.Message{
		ID:       uuid.New(),
		From:     from,
		To:       to,
		Subject:  subject,
		Priority: priority,
		Type:     msgType,
		Body:     body,
		Archived: false,
	}

	return db.Create(msg).Error
}

func handleList(args []string, db *gorm.DB) error {
	var agent string
	for i := 0; i < len(args); i++ {
		if args[i] == "--agent" && i+1 < len(args) {
			agent = args[i+1]
			i++
		}
	}

	var messages []inbox.Message
	err := db.Where("to = ? AND archived = ?", agent, false).Find(&messages).Error
	if err != nil {
		return err
	}

	for _, m := range messages {
		fmt.Printf("ID: %s | From: %s | Subject: %s\n", m.ID, m.From, m.Subject)
	}
	return nil
}

func handleArchive(args []string, db *gorm.DB) error {
	var id string
	for i := 0; i < len(args); i++ {
		if args[i] == "--id" && i+1 < len(args) {
			id = args[i+1]
			i++
		}
	}

	if id == "" {
		return errors.New("missing required flag: --id")
	}

	return db.Model(&inbox.Message{}).Where("id = ?", id).Update("archived", true).Error
}

func handleWatch(args []string, db *gorm.DB) error {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Simulate watching by waiting for context cancellation
	// In a real app, this would use a ticker or pubsub
	select {
	case <-ctx.Done():
		return nil
	}
}
