import (
	"bytes"
	"context"
	"fmt"
	"testing"
	"time"

	"github.com/godinj/drem-orchestrator/internal/inbox"
	"github.com/godinj/drem-orchestrator/internal/testutil"
	"github.com/google/uuid"
	"github.com/jinzhu/gorm"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestSendCommand_CreatesMessage(t *testing.T) {
	db := testutil.NewTestDB(t)
	defer db.Close()

	args := []string{
		"send",
		"--from", "kyle",
		"--to", "alex",
		"--subject", "Test",
		"--priority", "high",
		"--type", "request",
		"--body", "Hello",
	}

	err := run(args, db)
	require.NoError(t, err)

	var msg inbox.Message
	err = db.Where("from = ? AND to = ?", "kyle", "alex").First(&msg).Error
	require.NoError(t, err)

	assert.Equal(t, "Test", msg.Subject)
	assert.Equal(t, "high", msg.Priority)
	assert.Equal(t, "request", msg.Type)
	assert.Equal(t, "Hello", msg.Body)
}

func TestSendCommand_MissingRequiredFlags(t *testing.T) {
	db := testutil.NewTestDB(t)
	defer db.Close()

	// Missing --from
	args := []string{
		"send",
		"--to", "alex",
		"--subject", "Test",
	}

	err := run(args, db)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "missing required flag: --from")
}

func TestListCommand_ShowsUnreadMessages(t *testing.T) {
	db := testutil.NewTestDB(t)
	defer db.Close()

	agent := "mike"
	msg1 := inbox.Message{
		ID:       uuid.New(),
		From:     "alice",
		To:       agent,
		Subject:  "Msg 1",
		Archived: false,
	}
	msg2 := inbox.Message{
		ID:       uuid.New(),
		From:     "bob",
		To:       agent,
		Subject:  "Msg 2",
		Archived: false,
	}
	msg3 := inbox.Message{
		ID:       uuid.New(),
		From:     "charlie",
		To:       agent,
		Subject:  "Archived Msg",
		Archived: true,
	}

	err := db.Create(&msg1).Error
	require.NoError(t, err)
	err = db.Create(&msg2).Error
	require.NoError(t, err)
	err = db.Create(&msg3).Error
	require.NoError(t, err)

	// Capture stdout
	oldStdout := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	args := []string{"list", "--agent", agent}
	err = run(args, db)
	require.NoError(t, err)

	w.Close()
	os.Stdout = oldStdout

	var buf bytes.Buffer
	_, _ = buf.ReadFrom(r)
	output := buf.String()

	assert.Contains(t, output, msg1.Subject)
	assert.Contains(t, output, msg2.Subject)
	assert.NotContains(t, output, msg3.Subject)
}

func TestArchiveCommand_ArchivesMessage(t *testing.T) {
	db := testutil.NewTestDB(t)
	defer db.Close()

	msg := inbox.Message{
		ID:       uuid.New(),
		From:     "sender",
		To:       "receiver",
		Subject:  "Archive me",
		Archived: false,
	}
	err := db.Create(&msg).Error
	require.NoError(t, err)

	args := []string{"archive", "--id", msg.ID.String()}
	err = run(args, db)
	require.NoError(t, err)

	var updatedMsg inbox.Message
	err = db.First(&updatedMsg, msg.ID)
	require.NoError(t, err)
	assert.True(t, updatedMsg.Archived)
}

